import json,os,subprocess
from pathlib import Path
candidate=Path.cwd()
report=json.loads((candidate/"docs/measurements/shared-material-identity-144.json").read_text())
python=str(candidate/".venv/bin/python")
for label,source in (("baseline",Path("/tmp/vx144-baseline-reproduce")),("candidate",candidate)):
    env={**os.environ,"PYTHONPATH":str(source/"back")+":"+str(source/"mcp")}
    for method in ("analysis","search"):
        with open(f"/tmp/vx144-reproduced-{label}-{method}.json","w") as output:
            subprocess.run([python,"-c",report["reproduction"][method+"_python"]],cwd=source,env=env,check=True,stdout=output)
